const items = $input.all();
const result = [];

for (const item of items) {
  const text = item.json.textPlain || "";

  let nominal = 0;
  let keterangan = "Transaksi Jago";

  // POLA 1: Pembayaran Merchant (Contoh: GRAB FOOD)
  if (text.includes("Jumlah") && text.includes("Ke")) {
      const nominalMatch = text.match(/Jumlah\s+Rp\s*([\d\.]+)/);
      if (nominalMatch) {
          nominal = parseInt(nominalMatch[1].replace(/\./g, ''));
      }
      const keMatch = text.match(/Ke\s+([^\r\n]+)/);
      if (keMatch) {
          keterangan = keMatch[1].trim();
      }
  }

  // POLA 2: Penarikan Kantong (Contoh: sebesar Rp3.000 dari Kantong Tabung)
  else if (text.includes("sebesar Rp")) {
      const nominalMatch = text.match(/sebesar\s+Rp\s*([\d\.]+)/);
      if (nominalMatch) {
          nominal = parseInt(nominalMatch[1].replace(/\./g, ''));
      }
      const kantongMatch = text.match(/dari Kantong\s+([^\.]+)/);
      if (kantongMatch) {
          keterangan = "Tarik Kantong " + kantongMatch[1].trim();
      }
  }

  // POLA 3: Pemindahan Antar Kantong (Contoh: Rp300.000 telah dipindahkan...)
  else if (text.includes("telah dipindahkan dari Kantong")) {
      const nominalMatch = text.match(/Rp\s*([\d\.]+)\s+telah dipindahkan/);
      if (nominalMatch) {
          nominal = parseInt(nominalMatch[1].replace(/\./g, ''));
      }
      const kantongMatch = text.match(/ke Kantong\s+([^\.]+)/);
      if (kantongMatch) {
          keterangan = "Pindah ke Kantong " + kantongMatch[1].trim();
      }
  }

  // Memasukkan hasil ekstraksi ke dalam kotak paket baru
  result.push({
    json: {
      nominal: nominal,
      keterangan: keterangan
    }
  });
}

return result;
